import {reportTradingActivityRatio} from '../domain/brokerage-report.mjs';
import {tradeFillSummary,tradePrice} from './trade-fill-summary.mjs';
import {renderDataTable} from './data-table.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(v,digits=2)=>v===null||v===undefined?'미확인':Number(v).toLocaleString('ko-KR',{maximumFractionDigits:digits});
const pct=v=>v===null||v===undefined?'미확인':number(v*100,4)+'%';
const time=v=>v?new Date(v).toLocaleString('ko-KR',{timeZone:'Asia/Seoul',hour12:false})+' KST':'미확인';
const money=(v,c='KRW')=>number(v,c==='KRW'?2:8)+' '+c;
const labels={CASH:'현금',BTC_HOLD:'BTC 보유',TREND:'추세',BREAKOUT:'돌파',RECOVERY:'반등',NEWS:'뉴스',ENABLED:'운용 중',PAUSED:'중지',READY:'확인 완료',COLLECTING:'관측 자료 부족',FLOW_ADJUSTMENT_REQUIRED:'입출금 경계 대조 중'};
const label=v=>labels[v]??v??'미확인';
const table=(heads,rows,empty=heads[0]+' · 해당 기간 기록 0건')=>rows.length?renderDataTable(heads,rows.map(row=>row.map(esc))):'<p class="muted">'+esc(empty)+'</p>';
const section=(id,title,body)=>'<section id="'+id+'" class="panel"><h2>'+title+'</h2>'+body+'</section>';
const dl=rows=>'<dl>'+rows.map(([k,v])=>'<dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd>').join('')+'</dl>';
function executionOrders(execution,currency){
 if(!execution.orders.length)return '<p class="muted">해당 기간 주문 0건</p>';
 return '<ol class="report-orders">'+execution.orders.map(o=>{
  const fills=execution.trades.filter(f=>o.identifier&&f.exchangeOrderIdentifier===o.identifier).map(f=>({id:f.exchangeTradeId??f.runId,quantity:f.exactQuantity??f.quantity,gross:f.exactGross}));
  const actual=tradeFillSummary({filledQuantity:o.filledQuantity,feesPaid:o.fee,fills}),side={buy:'매수',sell:'매도'}[o.side]??o.side??'방향 미확인',unfilled=actual.quantity===0&&!['FILLED','PARTIALLY_FILLED','PARTIAL'].includes(o.state);
  const state={FILLED:'체결 완료',PARTIALLY_FILLED:'부분 체결',PARTIAL:'부분 체결',OPEN:'미체결',WAITING:'미체결',PENDING:'미체결',RESERVED:'전송 준비',CANCELLED:'취소',CANCELED:'취소',FAILED:'주문 실패',REJECTED:'주문 거절',UNKNOWN:'체결 결과 확인 필요'}[o.state]??o.state??'상태 미확인';
  const metrics=[['평균 '+side+'가',actual.averagePrice===null?unfilled?'미체결':'미확인':tradePrice(actual.averagePrice,currency)+' '+currency],['체결 금액',money(unfilled?0:actual.gross,currency)],['체결량',number(actual.quantity,8)],['수수료',money(actual.fee,currency)]];
  return '<li><div class="report-order-heading"><h3>'+esc(o.market)+' · '+esc(side)+'</h3><span>'+esc(state)+'</span></div><p class="report-order-time">주문 시각 '+esc(time(o.createdAt))+'</p><dl class="report-fill-metrics">'+metrics.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl>'+(!unfilled&&actual.gross===null?'<p class="warning">'+(actual.quantity>0?'체결 금액':'체결 수량')+' 대조 필요 · 원본 체결 자료는 근거 JSON과 CSV에서 확인할 수 있습니다.</p>':'')+'<details class="report-order-details"><summary>주문 조건과 가격 비교</summary>'+dl([['주문 / 유효 조건',o.type+' / '+(o.timeInForce??'거래소 기본')],['주문 수량',o.requestedQuantity??'미확인'],['최근 체결 시각',time(o.completedAt)],['관측 호가 예상 평균가',money(o.bookProjectedVwap,currency)],['가격 차이',o.shortfallBps===null||o.shortfallBps===undefined?'대조 자료 미확인':number(o.shortfallBps,3)+'bp'],['주문 ID',o.identifier??'미확인']])+'</details></li>';
 }).join('')+'</ol>';
}
function navChart(points,currency){
 const valid=points.filter(p=>p.equity!==null);if(valid.length<2)return '<p class="muted">이 보고서의 평가 관측이 2개 미만입니다.</p>';
 const from=Date.parse(valid[0].at),span=Math.max(1,Date.parse(valid.at(-1).at)-from),values=valid.map(p=>Number(p.equity)),low=Math.min(...values),high=Math.max(...values),range=Math.max(high-low,Math.max(1,high*.001)),segments=[];let segment=[];
 for(const p of valid){if(segment.length&&Date.parse(p.at)-Date.parse(segment.at(-1).at)>90000){segments.push(segment);segment=[];}segment.push(p);}segments.push(segment);
 const xy=p=>(45+(Date.parse(p.at)-from)/span*710).toFixed(2)+','+(175-(Number(p.equity)-low)/range*140).toFixed(2);
 return '<figure class="chart"><figcaption>운용자산 평가 추이 · '+esc(currency)+' · 입출금 포함</figcaption><svg viewBox="0 0 800 225" role="img" aria-label="'+esc(money(low,currency)+'부터 '+money(high,currency)+'까지의 운용자산 평가 추이')+'"><path d="M45 20V185H755" fill="none" stroke="currentColor" opacity="0.25"/>'+segments.map(s=>'<polyline class="series-a" points="'+s.map(xy).join(' ')+'" fill="none" stroke="currentColor" stroke-width="2"/>').join('')+'<text x="45" y="210">'+esc(time(valid[0].at))+'</text><text x="755" y="210" text-anchor="end">'+esc(time(valid.at(-1).at))+'</text><text x="45" y="18">'+esc(money(high,currency))+'</text></svg></figure>';
}
const link=(url,text)=>{try{const u=new URL(url);if(!['https:','http:'].includes(u.protocol))return esc(text);return '<a href="'+esc(u.href)+'" target="_blank" rel="noopener noreferrer">'+esc(text)+'</a>';}catch{return esc(text);}};
export const brokerageReportExportPath=(id,format='html')=>'/api/workspace/automated-trading/report-export?'+new URLSearchParams({reportId:id,format});
export function renderBrokerageReport(r){
 const c=r.currency,a=r.accounting,p=r.performance,risk=r.risk,cost=r.costs,research=r.research;
 const stats=[['운용자산',money(a.equity,c)],['순손익',money(r.summary.netPnl,c)],['입출금 조정 수익률',pct(p.flowAdjustedReturn)],['최대 낙폭',pct(risk.maxDrawdown)]];
 const header='<header><p class="eyebrow">VIV 인베스트먼츠 · 개인 포트폴리오 운용보고서</p><h1>'+esc(r.summary.headline)+'</h1><p>'+esc(r.summary.selection)+'</p><p class="muted">'+esc(time(r.generatedAt))+' · '+esc(c)+' 계좌 · 생성 시점의 저장 자료'+'</p><div class="stats">'+stats.map(([k,v])=>'<div><span>'+esc(k)+'</span><b>'+esc(v)+'</b></div>').join('')+'</div><details><summary>목차 · 12개 업무</summary><nav class="tabs" aria-label="보고서 항목">'+r.stages.map(s=>'<a class="badge" href="#'+s.id+'">'+esc(s.title)+'</a>').join('')+'</nav></details><p><a href="'+esc(brokerageReportExportPath(r.id,'csv'))+'" download>체결·세무 CSV</a> · <a href="'+esc('/api/workspace/automated-trading/reports?'+new URLSearchParams({reportId:r.id}))+'" download>근거 JSON</a> · <a href="/#minds?'+esc(new URLSearchParams({profileId:r.profileId,executionMode:'live',view:'operations'}))+'">운용 화면</a></p></header>';
 let body=section('mandate','01. 운용 위임',dl([['목표',r.mandate.objective],['기간',time(r.mandate.startsAt)+' ~ '+time(r.mandate.endsAt)],['운용 자금 / 1회 주문 한도',money(r.mandate.capitalLimit,c)+' / '+money(r.mandate.perOrderLimit,c)],['일일 손실 한도',money(r.mandate.dailyLossLimit,c)+' · 원금 대비 '+pct(risk.lossLimitRatio)],['투자 범위',r.mandate.marketCount+'개 승인 종목 · 전략·모델·종목·비중 자동 판단'],['운용 주기','3시간 판단 · 60초 평가 관측 · 판단 정산 후 보고서 자동 저장']]));
 body+=section('research','02. 시장과 뉴스',dl([['시장 기준 / 사용 가능 시각',time(research.marketAsOf)+' / '+time(research.availableAt)],['시장 자료',research.observedMarkets+' / '+research.approvedMarkets+'종목 · 출처 '+research.sourceCount+'건'],['학습 종료 / 예측 기간',time(research.trainedThrough)+' / '+(research.predictionHorizon??'미확인')],['6시간 시장 수익률 / 상승 종목 비중',pct(research.regime?.trend6h)+' / '+pct(research.regime?.breadth6h)],['시간봉 변동성 / 종목 간 편차',pct(research.regime?.volatility1h)+' / '+pct(research.regime?.dispersion6h)]])+'<h3>판단에 사용한 뉴스</h3>'+table(['자료','공개 시각','방향 점수','확신도','자산군'],research.news.map(n=>[n.title,time(n.publishedAt),number(n.direction,4),pct(n.confidence),n.assetClass??'확인 중']))+research.news.filter(n=>n.source).map(n=>'<p>'+link(n.source,n.title)+'</p>').join('')+'<p class="muted">동일 사건의 버전은 최신 자료로 묶어 표시합니다. 판단에 사용한 원문과 당시 입력도 보존합니다.</p>');
 body+=section('selection','03. 전략과 종목 선택',table(['전략','비용 반영 추정 수익률','뉴스 조정','배정 비중','표본','유효 표본'],research.experts.map(e=>[label(e.mode),pct(e.expectedNetReturn),pct(e.newsAdjustment),pct(e.allocation),e.samples,number(e.effectiveSamples,1)]))+'<p class="muted">조건부 과거 자료 추정 · '+esc(research.predictionHorizon??'')+' 예측 · 편도 비용 가정 '+number(research.costBps)+'bp. 실제 체결 성과는 07항에 구분합니다.</p>');
 body+=section('allocation','04. 자산 배분',table(['종목','현재 비중','목표 비중','현재 평가액','목표 금액'],r.allocation.map(t=>[t.instrumentId.replace('crypto:upbit:','').replace('CASH:','현금 '),pct(t.currentWeight),pct(t.targetWeight),money(t.currentValue,c),money(t.targetValue,c)])));
 body+=section('execution','05. 주문과 체결',dl([['주문 / 체결 / 미확정',r.execution.orders.length+' / '+r.execution.fillCount+' / '+r.execution.pending+'건'],['누적 체결금액 / 운용자산',pct(reportTradingActivityRatio(r.execution.trades,a.equity))]])+'<details class="report-order-details"><summary>집계·가격 비교 기준</summary>'+dl([['비율 계산 기준','매수·매도 체결금액 합계 ÷ 보고서 운용자산. 연간 펀드 회전율과 구분합니다.'],['가격 비교 기준','실제 체결 평균가와 주문 당시 관측 호가의 체결 예상 평균가']])+'</details>'+executionOrders(r.execution,c));
 body+=section('settlement','06. 정산과 보관',dl([['최초 원금',money(a.initialCapital,c)],['추가 편성 / 회수',money(a.additionalDeposits,c)+' / '+money(a.withdrawals,c)],['순투입 원금',money(a.netContributions,c)],['현금 / 주문 예약',money(a.cash,c)+' / '+money(a.reservedCash,c)],['원장 / 평가 시각',time(a.ledgerAsOf)+' / '+time(a.valuationAt)],['거래소 원화 잔고',a.broker?money(a.broker.account.available,c)+' 가용 · '+money(a.broker.account.locked,c)+' 주문 잠금':'조회 재시도'],['거래소 현금과 운용 현금 차이',a.broker?money(a.broker.cashDifference,c)+' · 거래소 총액과 이 운용의 배정액 대조':'조회 재시도']])+table(['보유 종목','수량','취득 원가','평가액','평가 손익'],a.positions.map(v=>[v.market,v.quantity,money(v.costBasis,c),money(v.marketValue,c),money(v.unrealizedPnl,c)]))+'<h3>입출금</h3>'+table(['시각','금액','원장 ID'],a.flows.map(f=>[time(f.at),money(f.amount,c),f.id])));
 body+=section('performance','07. 수익과 기여',navChart(p.chart,c)+table(['조회 기간','실제 관측 시작','수익률','자료 범위'],p.periods.map(v=>[v.days+'일',time(v.from),pct(v.return),v.fullWindow?'전 기간':'운용 개시 이후 관측 구간']))+dl([['실현 / 평가 손익',money(a.realizedPnl,c)+' / '+money(a.unrealizedPnl,c)],['입출금 조정 수익률',pct(p.flowAdjustedReturn)+' · 경과 시간 가중 Modified Dietz'],['일 단위 환산',pct(p.dailyEquivalentReturn)+' · 운용 경과 시간의 기하 환산'],['관측 시간가중 수익률',pct(p.timeWeightedReturn)]])+'<section class="report-comparison" aria-labelledby="report-comparison-title"><h3 id="report-comparison-title">동일 구간 수익률 비교</h3><p class="muted">'+esc(time(p.benchmark.from)+' ~ '+time(p.benchmark.to))+'</p><dl class="report-comparison-metrics">'+[['포트폴리오',pct(p.benchmark.portfolioReturn)],['BTC 보유',pct(p.benchmark.btcNetReturn)],['현금','0%'],['BTC 대비 초과수익',pct(p.benchmark.excessReturn)]].map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><p class="muted">BTC는 같은 관측 구간의 매수·매도 최우선 호가와 확인된 수수료 기준입니다.</p></section><h3>종목별 손익 기여</h3>'+table(['종목','매수 총액','매도 총액','수수료','실현 손익','평가 손익','순손익'],p.attribution.map(v=>[v.instrumentId.replace('crypto:upbit:',''),money(v.buyGross,c),money(v.sellGross,c),money(v.fees,c),money(v.realizedPnl,c),money(v.unrealizedPnl,c),money(v.netPnl,c)]))+'<p class="muted">일 환산 수익률은 해당 경과 기간의 환산값입니다.</p>');
 body+=section('risk','08. 위험 관리',dl([['완전 구간 MDD / 관측 MDD',pct(risk.maxDrawdown)+' / '+pct(risk.observedMdd)],['회복 상태',risk.recovered===null?'관측 중':risk.recovered?'회복 완료':'미회복 · 현재까지 '+number(risk.recoveryMs/3600000)+'시간'],['위험 계산 근거',risk.cashOnlySinceStart?'전 기간 현금 원장 대조':'60초 평가 관측 · '+risk.points+'개 · 최대 간격 '+number(risk.maxGapMs/1000)+'초'],['최대 단일 종목 비중',pct(risk.concentration)],['관측 주기 VaR 95% / ES 95%',pct(risk.var95)+' / '+pct(risk.expectedShortfall95)]])+table(['가상 가격 충격','추정 손익'],risk.stress.map(s=>[pct(s.shock),money(s.estimatedPnl,c)]))+'<p class="muted">입출금은 외부 현금흐름으로 분리합니다. 가상 충격은 현재 위험자산이 동시에 같은 폭으로 움직이는 가정입니다.</p>');
 body+=section('costs','09. 운용 비용',dl([['실제 거래 수수료',money(cost.tradingFees,c)+' · 순손익에 이미 반영'],['이번 운용의 외부 AI 호출',cost.modelCalls+'회 · 입력 '+cost.inputTokens+' / 출력 '+cost.outputTokens+'토큰'],['AI 청구 금액',cost.modelTotals.length?cost.modelTotals.map(v=>money(v.amount,v.currency)).join(', '):cost.unpricedModelCalls?'공급자 청구액 대조 중':'0 KRW'],['금액 미확정 호출',cost.unpricedModelCalls+'회'],['AI 비용 포함 순손익',money(cost.allInPnl,c)],['비용 집계 경계','운용 개시 이후 실제 호출 · 개시 전 학습·개발 비용 별도']])+table(['요청 ID','용도','모델','입력 토큰','출력 토큰','청구액'],cost.modelUsage.map(v=>[v.requestId,v.kind,v.model,v.inputTokens,v.outputTokens,v.cost===null?'청구액 대조 중':money(v.cost,v.currency)])));
 body+=section('review','10. 모델 사후 평가',dl([['운용 중 모델 그래프',r.governance.graphHash],['판단 당시 그래프',r.governance.decisionGraphHash],['판단 결과 해시',r.governance.evaluationHash],['자동 채택 영수증',r.governance.automaticPromotions.length+'건 · 실제 새 모델 판단 대조 대상']])+table(['시각','변경 유형','영수증 ID'],r.governance.changes.map(v=>[time(v.at),v.kind,v.id]))+'<p class="muted">학습 추정치, 독립 관측 비교, 실제 체결 성과와 자동 채택 영수증을 각각 보존합니다.</p>');
 body+=section('tax','11. 세무 기초자료',dl([['처분 건수',r.tax.disposalCount+'건'],['원장 실현 손익 / 거래 수수료',money(r.tax.realizedPnl,c)+' / '+money(r.tax.feesPaid,c)],['제공 자료','CSV의 체결 시각·종목·수량·금액·수수료·실현 손익·거래소 ID'],['신고 대조','거래소 세무 자료와 취득 원가, 계좌 이동, 적용 과세 기간을 대조']]));
 body+=section('operations','12. 운영과 다음 계획',dl([['운용 상태',label(r.operations.policyStatus)+' · '+(r.operations.runtime?.state??'상태 갱신 중')],['다음 판단',time(r.operations.nextAnalysisAt)],['계좌와 운용 ID',r.accountId+' / '+r.activationId]])+table(['업무','담당 경로'],r.governance.roles)+table(['자료 품질','후속 처리'],r.operations.coverage.map(v=>[v.code,v.detail]),'현재 보고서 자료 대조 완료')+'<p class="muted">토스 주식 계좌는 원화·달러, 시장 달력과 실제 주문 연결을 별도로 대조합니다. 현재 보고 범위는 위에 표시한 '+esc(r.accountId)+' 운용입니다.</p>');
 const footer='<footer><p>자료 집계 '+esc(time(r.sourceCutoffAt??r.generatedAt))+' · 보고서 생성 '+esc(time(r.generatedAt))+'</p>'+(r.supersedes?'<p>정정 이력 · 평가 시각과 현재 보유 기준 정리 · <a href="'+esc(brokerageReportExportPath(r.supersedes))+'">원보고서</a></p>':'')+'<p>보고서 '+esc(r.reportHash)+'</p><p>작성 기준: '+link('https://www.cfainstitute.org/insights/professional-learning/refresher-readings/2026/portfolio-management-overview','CFA 포트폴리오 관리 절차')+' · '+link('https://www.gipsstandards.org/standards/gips-standards-for-firms/gips-standards-handbook-for-firms/','GIPS 성과 계산·비용 공시 자료')+'</p></footer>';
 return '<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>포트폴리오 운용보고서 · '+esc(time(r.generatedAt))+'</title><link rel="stylesheet" href="/ui/tailwind.css"><link rel="stylesheet" href="/ui/research-report.css"></head><body class="research-report brokerage-report"><main>'+header+body+footer+'</main></body></html>';
}
export function brokerageTradeCsv(r){
 const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';
 const rows=[['체결 시각 UTC','종목','방향','수량','체결 금액','수수료','실현 손익','통화','거래소 체결 ID','주문 ID','개별 체결가'],...r.execution.trades.map(t=>[t.at,t.instrumentId,t.side,t.exactQuantity,t.exactGross,t.exactFee,t.exactRealizedPnl,r.currency,t.exchangeTradeId,t.exchangeOrderIdentifier,Number.isFinite(t.fillPrice)&&t.fillPrice>0?t.fillPrice:''])];
 return '\ufeff'+rows.map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';
}
